unitsize(1.5 cm);

pair A, B, P, R, S, T;
pair[] O;
real[] r;

r[1] = 2;
r[2] = 3;

S = (-2*r[1],0);
O[1] = (-r[1],0);
R = (0,0);
O[2] = (r[2],0);
T = (2*r[2],0);
